  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "完整定义了层或算子的输入、参数、运行状态、放置计划、执行身份、版本及可见输出，动机与容量和完整依赖路径相连。本章核心范围为一次层或算子执行，不把该提交点声称为整请求 token 提交。",
      "evidence": [
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "设一层或算子为 $F_θ(X;S)$，其中 X 是输入，θ 是权重或参数，S 是必要运行状态，例如 KV、mask、位置和归一化统计。"
        },
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "状态可概括为当前阶段、私有结果缓冲、已完成分片集合、未完成物理访问集合和可见输出 $Y_{vis}$。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "输出轴 scatter、归约轴部分和及 attention 统计量合并的代数条件正确；明确区分实数等价、浮点容差、离散选择和质量契约。PowerInfer 的预测漏项及模型变体、FlexGen 的量化与 CPU delegation 组合限制均与所供原文相符，来源日期处于 cutoff 内。",
      "evidence": [
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "不能先对每个分片做 softmax 再等权平均，因为各分片的概率质量不同。"
        },
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "这个公式与一次性完整 softmax 在实数上等价；浮点上仍可能因指数、求和顺序和 dtype 不同而产生差异。"
        },
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "若要求精确原函数，必须补算或验证；若允许近似，则预测器、校准分布和质量回归都属于模型契约。"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "分片数学、私有结果、合并方式、失败后的物理排空和共同提交意图已有解释，但标为完整算法的伪代码缺少成功完成记录的接收、DONE 更新及进入合并前的成功等待规则；空分片完成状态与提交谓词也未明确衔接。当前脚本没有执行正常共同提交来验证这段推进路径。",
      "evidence": [
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "阶段[u]=DONE_EMPTY; 不建立无意义的同步"
        },
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "发布完成记录 (r,l,g,v,π,W.version,KV.version,结果句柄)"
        },
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "仅当所有必需分片为 DONE，且"
        }
      ]
    },
    "cost": {
      "assessment": "partial",
      "reason": "三条放置路径的设定算术、MiB/GiB 换算、共享单资源流量合计及全驻留对照正确，准备、同步和在途容量边界也有说明。但一般资源周期下界错误地跨不同资源求和，可能把可并行服务需求算成必需串行时间，影响候选可行性与选择。",
      "evidence": [
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "$P≥Σ_r Q_r/B_r$，并同时满足依赖路径和计算资源的限制。"
        },
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "若容量允许全部驻留，人为加入 $W_c/B_l$ 再把异构方案判为更优，是把可选搬运当成了必然成本。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "对 batch、历史、容量、热点、预测误差、量化、链路和共享内存分别解释保留的不变量及变化的成本，提供条件化反转算例。真实 batch 变化不能直接沿用算例常数，正文已把这些数值限定为保持其他设定的解析比较。",
      "evidence": [
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "这个对照说明：容量变化会改变候选集合，而不只是改变某个常数。"
        },
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "任何结论都必须带 batch、链路、冷比例和容量条件。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "给出了 CPU 计算、共享带宽、同步、布局、数值和身份错配的竞争解释与可控实验，并区分代数、浮点与设备测量。脚本存在有辨别力的稠密参考、直接 softmax 参考和负对照；其覆盖不足不能被成功退出掩盖，具体遗漏在 test_assessment 中列明。",
      "evidence": [
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "固定历史只扫 batch，再固定 batch 只扫历史；分别记录 CPU 计算、KV 字节、预测活跃数和排队"
        },
        {
          "path": "knowledge/algorithms/heterogeneous-execution.md",
          "quote": "运行时检查 finite、shape、版本和提交代次可以发现一部分状态错误，但不能替代独立数值参考。"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-ALG-020-R1-COST-001",
      "criterion": "cost",
      "evidence": "当前正文先定义“设资源 r 在每个工作单位上累计承担 $Q_r$ 字节，在该并发条件下可持续带宽为 $B_r$”，随后写“$P≥Σ_r Q_r/B_r$”。所供 K-HW-003 摘录的对应推导则使用 max_r Q_r/B_r。",
      "impact": "跨独立资源求和不是一般成立的周期必要下界。例如两个独立资源每工作单位各服务 64 MiB、各有 8 GiB/s 带宽，缓冲充分时可同时服务，稳态周期可为 7.8125 ms；正文公式却要求至少 15.625 ms。该错误会排除实际可行的重叠计划。",
      "blocking": true,
      "required_revision": "改为对每个物理资源先合计其承担的全部流量，再取 max_r(Q_r/B_r)，并与计算资源和依赖限制共同取必要下界；只有存在额外串行依赖时才加入相应路径时间。保留现有同一 DRAM 上 128 MiB 的正确算例，增加能区分跨资源求和与取最大的检查。"
    },
    {
      "id": "K-ALG-020-R1-ALGORITHM-001",
      "criterion": "algorithm",
      "evidence": "步骤2设置“阶段[u]=DONE_EMPTY”或 READY/SUBMITTED；步骤3只“发布完成记录”；步骤4只展开失败分支；步骤5直接合并；步骤6要求“仅当所有必需分片为 DONE，且”。伪代码没有接收成功完成并推进 DONE 的规则，也没有明确在读取分片结果前等待全部成功。检查脚本中 good 路径只注入并拒绝旧代 CPU 完成，没有完成当前代 CPU/GPU 的正常共同提交。",
      "impact": "正文轨迹表达了正确意图，但当前伪代码不足以独立恢复成功推进：按显式状态更新执行，非空任务不会进入 DONE；直接进入步骤5则可能读取尚未完成的结果。空分片应排除于等待集合还是作为成功终态，也需要与提交条件一致。",
      "blocking": true,
      "required_revision": "补全成功等待和完成接收规则：按冻结身份与版本接收完成、记录对应分片成功终态，所有必要结果就绪后才合并；明确 DONE_EMPTY 与提交谓词的关系。提交与取消/失败资格检查应有明确的串行或原子边界。让配套模型实际覆盖两种完成顺序的正常提交及单侧空分片，并用缺少完成门控的错误变体验证判据有辨别力。"
    }
  ],
  "limitations": [
    "CPU 有理数、浮点和协议模型不能证明真实 GPU 可见性、DMA 最后访问、PCIe/NUMA 争用、统一内存迁移、kernel 性能或服务 SLO；正文已正确声明这些边界。",
    "没有读取 S-CPU-TUNING 的原始教程或源码归档，只按所供完整来源说明核对相关机制。",
    "本复核审计了用户提供的 remote_bwrap 实际执行记录，未独立重跑 Python 文件，也未从文件系统重新计算绑定哈希。",
    "相对链接的路径组织可以从所供内容核对，但未检查 reader.html 实体、PDF 图像或所有链接目标的实际存在性。",
    "没有目标模型质量回归、真实设备性能或知识改善 Agent 使用效果的实验；这些范围不因模型检查通过而成立。"
  ],
  "checks": [
    {
      "script": "tools/check_k_alg_020_full.py",
      "args": []
    }
  ],
  "reading_scope": "按用户暴露的提取文本阅读。以下为完整所供文件，范围均为零基半开字符区间：AGENTS.md [0,567)；docs/knowledge-method.md [0,2251)；docs/knowledge-review.md [0,3016)；knowledge/algorithms/heterogeneous-execution.md [0,11267)；knowledge/sources/S-POWERINFER.md [0,739)；knowledge/sources/S-FLEXGEN.md [0,989)；knowledge/sources/S-CPU-TUNING.md [0,731)；knowledge/sources/S-TORCH-NUMERIC.md [0,532)；knowledge/hardware/cpu-linear-kernels.md [0,4016)；knowledge/hardware/shared-memory-paths.md [0,3129)；knowledge/algorithms/kv-offload-prefetch.md [0,3710)；knowledge/algorithms/weight-expert-offload.md [0,3216)；knowledge/engine-index/vllm-model-runner.md [0,2207)；knowledge/algorithms/tiered-residency.md [0,4244)；knowledge/models/recommendation-inference.md [0,3902)；knowledge/models/graph-inference.md [0,3892)；references/S-POWERINFER/fulltext.txt [0,77788)，含所供 PDF pp.1–15 提取文本；references/S-FLEXGEN/fulltext.txt [0,85794)，含所供 PDF pp.1–25 提取文本；references/S-TORCH-NUMERIC/fulltext.txt [0,10998)。tools/check_k_alg_020_full.py 阅读了 candidate.test_script 提供的完整脚本，从导入至 main 入口。以下仅阅读指定摘录，未列入 documents：knowledge/hardware/host-device-transfer.md [0,5666)；knowledge/algorithms/async-scheduling.md [4000,9666)；knowledge/system-semantics/cancellation-resource-completion.md [0,1666)、[12000,16000)；knowledge/hardware/rocm-execution.md [8000,10808)、[12000,14858)；knowledge/hardware/metal-unified-memory.md [0,1959)、[12000,15707)；knowledge/models/moe-routing.md [8000,9666)、[12000,16000)；knowledge/system-semantics/design-synthesis.md [4000,9666)。完整阅读了所供 author_notes 与 actual_preflight 的 stdout、stderr、执行参数、脚本身份和隔离范围。上述完整阅读仅指所供文本，不表示阅读了 PDF 图像、reader.html、外链或上游源码。",
  "test_assessment": "所供 actual_preflight 记录绑定脚本 SHA256 315056e7a9120ad0c351749c4eb0d31f589fbea4ba4358b39ae68a9aaefb3b14，实际使用 Python 3.12 的 -I -S -B -X utf8 参数在 remote_bwrap 隔离环境执行，returncode=0、stderr 为空、未超时。此为协调者提供的真实运行证据，不能归为作者已执行或本复核独立重跑。逐项审查脚本后，有理数 matvec 以完整输出位置为参考，能够检出缺失分片和混用旧输入；分片统计量与直接整行 softmax 比较，并实际检出等权平均错误，具有机制辨别力。输出切分覆盖一个非整除维度、空集合和非连续通道；softmax 仅覆盖两个非空分区，没有验证正文的空分区及全空行分支。提交模型的预期不变量是旧身份不能改变当前 pending、parts 或 committed，负对照确实接受了旧结果；但 strict=False 同时移除了代次和版本检查，不能证明单独遗漏代次检查能被现有输入检出，因为该轨迹同时改变 g 和 v。脚本没有执行正常双侧共同提交、单侧空分片、取消/失败排空、计划或权重/状态版本匹配，故其 PASS 不能验证完整 ExecuteHybridLayer。成本部分验证了具体换算、路径算术和临界点，单 DRAM 的双流负对照正确；但没有多独立资源案例，未触及正文错误的跨资源求和公式。本复核另在工具 V8 中独立计算了两个独立资源各需 7.8125 ms 时可并行而正文给出 15.625 ms 的反例，并检查了 DONE_EMPTY 与仅接受 DONE 的字面谓词差异；这些是局部解析核验，不是 Python 脚本执行或设备实验。作者关于尚未执行脚本及设备验证范围的声明诚实，但其完整算法与一般成本下界仍需修订。"
}
